#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MOD_A=998244353,MOD_B=1e9+7;
const int MAXN=2e6,MAX_LIMIT=1e6;
ll total_n,counter;
int count_total,answer_value,depth_limit,pw_vals[MAXN],sum_vals[MAXN];
vector<int> storage[MAXN];

inline int mod_sub(int x,int y,int m){return (x-y<0)?x-y+m:x-y;}
inline int mod_add(int x,int y,int m){return (x+y>=m)?x+y-m:x+y;}
inline void build(int level,int val){
	if(val<=total_n){
		++count_total;int x=mod_sub(count_total,val,MOD_A);
		storage[level-1].push_back(x);sum_vals[level-1]=mod_add(sum_vals[level-1],x,MOD_B);
	}
	if(level>6) return;
	for(int i=0;i<=9;++i) build(level+1,val*10+i);
}
inline void process(int level,ll current){
	if(current>total_n) return;
	if(level>1){
		if(10ll*current*MAX_LIMIT>total_n && 1ll*(current+1)*MAX_LIMIT-1<=total_n){
			for(int i=0;i<7;++i){
				int x=((counter-1ll*current*pw_vals[i])%MOD_A+MOD_A)%MOD_A;
				int p=lower_bound(storage[i].begin(),storage[i].end(),MOD_A-x)-storage[i].begin();
				answer_value=mod_add(answer_value,mod_add(1ll*x*storage[i].size()%MOD_B,sum_vals[i],MOD_B),MOD_B);
				answer_value=mod_sub(answer_value,1ll*MOD_A*(storage[i].size()-p)%MOD_B,MOD_B);
			}
			counter+=count_total;
			return;
		}
		++counter;answer_value=mod_add(answer_value,((counter-current)%MOD_A+MOD_A)%MOD_A,MOD_B);
	}
	for(int i=(level==1?1:0);i<=9;++i) process(level+1,current*10+i);
}
int main(){
	scanf("%lld",&total_n);
	pw_vals[0]=1;for(int i=1;i<9;++i) pw_vals[i]=10*pw_vals[i-1];
	build(1,0);
	for(int i=0;i<7;++i)
		sort(storage[i].begin(),storage[i].end());
	process(1,0);
	printf("%d\n",answer_value);
	return 0;
}
